import{_ as t,o as s,c as i,ao as a}from"./chunks/framework.BHJkOVb-.js";const u=JSON.parse('{"title":"Batch runs and benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"batch_run.md","filePath":"batch_run.md","lastUpdated":null}'),n={name:"batch_run.md"};function r(h,e,o,l,d,c){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="run-batch" tabindex="-1">Batch runs and benchmark <a class="header-anchor" href="#run-batch" aria-label="Permalink to &quot;Batch runs and benchmark {#run-batch}&quot;">​</a></h1><p><a href="/AustralianElectricityMarkets.jl/previews/PR240/examples/run_nemde#run-nemde">Running NEMDE dispatch</a> runs a few intervals in one Julia session. For days or months of intervals, the repository ships a batch runner and a report script in <code>scripts/</code>. Both read the local cache and download nothing: populate the tables of <code>table_requirements(NEMDEConfiguration())</code> for the period first. They run from the repository root in the Simulations test environment.</p><h2 id="The-batch-runner" tabindex="-1">The batch runner <a class="header-anchor" href="#The-batch-runner" aria-label="Permalink to &quot;The batch runner {#The-batch-runner}&quot;">​</a></h2><p><code>scripts/batch_run.jl</code> runs intervals against the published NEMDE outcome. A supervisor process schedules trading days and runs each in a fresh worker process, which builds the <code>System</code> with <code>nem_system</code>, the models with <code>nem_dispatch_sequence</code> and writes the comparisons as CSV files under the run folder. <code>--output</code> names the run folder, which must not exist.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=AustralianElectricityMarketsSimulations/test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/batch_run.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:right;">Mode</th><th style="text-align:right;">Options</th><th style="text-align:right;">What is run</th></tr></thead><tbody><tr><td style="text-align:right;">Whole days</td><td style="text-align:right;"><code>--first DATE --last DATE --hours H --seed S</code></td><td style="text-align:right;">Trading days of the period in a seeded random order, until <code>--hours</code> of wall time have elapsed; the day in progress is finished</td></tr><tr><td style="text-align:right;">One range</td><td style="text-align:right;"><code>--start DATETIME --intervals N</code></td><td style="text-align:right;"><code>N</code> consecutive intervals from the interval ending at <code>--start</code>, within its trading day</td></tr><tr><td style="text-align:right;">Interval list</td><td style="text-align:right;"><code>--intervals-file PATH</code></td><td style="text-align:right;">The intervals of a CSV with the header <code>interval</code>, each solved on its own</td></tr><tr><td style="text-align:right;">Random sample</td><td style="text-align:right;"><code>--sample N</code></td><td style="text-align:right;"><code>N</code> distinct intervals drawn at random over <code>--first</code> to <code>--last</code> (seed <code>--seed</code>), each solved on its own</td></tr></tbody></table><p>Two switches change the model:</p><ul><li><p><code>--closed-loop true</code> starts each interval after the first from the previous solve rather than from AEMO&#39;s observed state (<code>NEMClosedLoopDispatchProblem</code>). It needs consecutive intervals, so it is rejected with <code>--sample</code> and <code>--intervals-file</code>.</p></li><li><p><code>--fast-start false</code> solves one model per interval, without the fast-start inflexibility profiles. By default each interval runs NEMDE&#39;s commitment and dispatch runs when the <code>System</code> has a fast-start unit; see <a href="/AustralianElectricityMarkets.jl/previews/PR240/examples/nemde_fast_start#nemde-fast-start">Fast-start dispatch</a>.</p></li></ul><p>Each day folder holds the comparisons with the published outcome (<code>comparison_prices.csv</code>, <code>comparison_dispatch.csv</code>, <code>comparison_interconnectors.csv</code>, <code>comparison_fcas_prices.csv</code>), a <code>summary.csv</code> of paired errors, the skipped constraints and constraint violations, solver statistics and phase timings. Energy prices compare the solved price with the published regional original price (ROP). <code>scripts/README.md</code> lists every option, output file and timing column.</p><h2 id="The-report" tabindex="-1">The report <a class="header-anchor" href="#The-report" aria-label="Permalink to &quot;The report {#The-report}&quot;">​</a></h2><p><code>scripts/simulation_statistics.jl</code> summarises one or more saved runs without solving anything: runtime breakdowns, error distributions by region, service, interconnector and unit, the energy price tail and the largest errors.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=AustralianElectricityMarketsSimulations/test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/simulation_statistics.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [RUN...] [--output FOLDER] [--hive FOLDER]</span></span></code></pre></div><p>The report goes to <code>&lt;first run&gt;/simulation_statistics/</code> unless <code>--output</code> is given. With <code>--hive</code>, dispatch errors are also grouped by each unit&#39;s region, dispatch type and schedule type. Closed-loop and open-loop days are never pooled.</p><h2 id="The-nempy-benchmark" tabindex="-1">The nempy benchmark <a class="header-anchor" href="#The-nempy-benchmark" aria-label="Permalink to &quot;The nempy benchmark {#The-nempy-benchmark}&quot;">​</a></h2><p><a href="https://github.com/UNSW-CEEM/nempy" target="_blank" rel="noreferrer">nempy</a> publishes a benchmark of its own NEMDE replica over 1000 random dispatch intervals of July to December 2024. <code>benchmarking/nempy_2024h2_intervals.csv</code> holds the same intervals, so the run can be compared like for like, each interval solved independently:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=AustralianElectricityMarketsSimulations/test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/batch_run.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --intervals-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmarking/nempy_2024h2_intervals.csv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --hours</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/aem_validation/nempy-2024h2&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=AustralianElectricityMarketsSimulations/test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/simulation_statistics.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/aem_validation/nempy-2024h2&quot;</span></span></code></pre></div><p>The report&#39;s <code>energy_price</code> section gives the signed error <code>ROP_solved - ROP_published</code>. nempy&#39;s published energy price error over these intervals, in $/MWh against the published ROP:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Mean</th><th style="text-align:right;">Median</th><th style="text-align:right;">p5</th><th style="text-align:right;">p95</th></tr></thead><tbody><tr><td style="text-align:right;">0.13818</td><td style="text-align:right;">0.0</td><td style="text-align:right;">-0.13336</td><td style="text-align:right;">0.01353</td></tr></tbody></table><p><code>benchmarking/README.md</code> describes how the intervals were drawn and the cache the run needs.</p>`,19)])])}const k=t(n,[["render",r]]);export{u as __pageData,k as default};
